import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), sceneRoot=$('#scene');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9cae9c); scene.fog=new THREE.FogExp2(0x9cae9c,.012);
const camera=new THREE.PerspectiveCamera(72,innerWidth/innerHeight,.1,220); camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15; renderer.outputColorSpace=THREE.SRGBColorSpace; sceneRoot.appendChild(renderer.domElement);
const hemi=new THREE.HemisphereLight(0xdce9d5,0x293329,2.1); scene.add(hemi); const sun=new THREE.DirectionalLight(0xffe6bd,3.0); sun.position.set(-35,55,28); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-55; sun.shadow.camera.right=55; sun.shadow.camera.top=55; sun.shadow.camera.bottom=-55; scene.add(sun);
const materials={}; const mat=(color,rough=.9)=>new THREE.MeshStandardMaterial({color,roughness:rough});
const groundMat=mat(0x596c49), trunkMat=mat(0x59402d), barkLight=mat(0x78543a), pineA=mat(0x304b3b), pineB=mat(0x3c5a43), pineC=mat(0x536d4c), stoneMat=mat(0x777e75), stoneLight=mat(0x929589), grassMat=mat(0x829457), berryMat=mat(0x4c7642), berryFruit=mat(0x9c5e65), beaconMat=new THREE.MeshStandardMaterial({color:0xf6d895,emissive:0xffa735,emissiveIntensity:2});
let seed=2913; function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296} function heightAt(x,z){return Math.sin(x*.071)*1.45+Math.cos(z*.064)*1.22+Math.sin((x+z)*.039)*1.65+Math.cos(x*.027-z*.05)*1.4}
// Soft, rolling terrain with a winding meadow through the cedar forest.
const N=120, SIZE=180, verts=[],idx=[],cols=[]; for(let iz=0;iz<=N;iz++)for(let ix=0;ix<=N;ix++){const x=(ix/N-.5)*SIZE,z=(iz/N-.5)*SIZE; const h=heightAt(x,z);verts.push(x,h,z);const meadow=Math.max(0,1-Math.abs(x-Math.sin(z*.038)*4)/12);const c=new THREE.Color().setRGB(.28+meadow*.12+rand()*.025,.36+meadow*.11+rand()*.025,.23+meadow*.07);cols.push(c.r,c.g,c.b);if(ix<N&&iz<N){const a=iz*(N+1)+ix,b=a+1,c=a+N+1,d=c+1;idx.push(a,c,b,b,c,d)}}
const terrainGeo=new THREE.BufferGeometry();terrainGeo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));terrainGeo.setAttribute('color',new THREE.Float32BufferAttribute(cols,3));terrainGeo.setIndex(idx);terrainGeo.computeVertexNormals();const terrain=new THREE.Mesh(terrainGeo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));terrain.receiveShadow=true;scene.add(terrain);
const player={pos:new THREE.Vector3(0,heightAt(0,15)+1.72,15),vel:new THREE.Vector3(),yaw:0,pitch:0,health:100,food:100,water:100,temp:37,wood:0,stone:0,fiber:0,berries:0,axe:false,spear:false,fire:false,flare:1,slot:0,gathered:0,elapsed:0,firePos:null,won:false,dead:false}; camera.position.copy(player.pos);
const worldNodes=[]; function addNode(group,type,label,quantity,pos){group.position.set(pos.x,heightAt(pos.x,pos.z),pos.z);group.userData={node:true,type,label,quantity,alive:true};scene.add(group);worldNodes.push(group);return group}
function makeTree(x,z,scale=1){const g=new THREE.Group(),h=5.5*scale;const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.24*scale,.38*scale,h*.57,7),trunkMat);trunk.position.y=h*.285;trunk.castShadow=true;g.add(trunk);const bark=new THREE.Mesh(new THREE.CylinderGeometry(.09*scale,.14*scale,h*.34,6),barkLight);bark.position.set(.03*scale,h*.5,0);bark.rotation.z=-.12;g.add(bark);for(let i=0;i<4;i++){const radius=(2.05-i*.32)*scale,height=(2.7-i*.2)*scale;const cone=new THREE.Mesh(new THREE.ConeGeometry(radius,height,7),[pineA,pineB,pineC][i%3]);cone.position.y=(2.65+i*.72)*scale;cone.rotation.y=rand()*6.2;cone.castShadow=true;g.add(cone)}return addNode(g,'tree','CEDAR TREE',player.axe?3:2,{x,z})}
function makeRock(x,z){const g=new THREE.Group();const r=new THREE.Mesh(new THREE.DodecahedronGeometry(.63+rand()*.28,0),stoneMat);r.scale.set(1.25,.78,.9);r.rotation.set(rand(),rand()*4,rand());r.position.y=.38;r.castShadow=true;g.add(r);const r2=new THREE.Mesh(new THREE.DodecahedronGeometry(.32,0),stoneLight);r2.position.set(.55,.28,.15);r2.scale.set(1,.75,.9);g.add(r2);return addNode(g,'stone','FLINT OUTCROP',2,{x,z})}
function makeBush(x,z){const g=new THREE.Group();for(let i=0;i<5;i++){const b=new THREE.Mesh(new THREE.IcosahedronGeometry(.42,1),berryMat);b.position.set((rand()-.5)*.8,.38+rand()*.35,(rand()-.5)*.65);b.scale.set(1,.8,1);g.add(b)}for(let i=0;i<5;i++){const berry=new THREE.Mesh(new THREE.SphereGeometry(.075,8,6),berryFruit);berry.position.set((rand()-.5)*.65,.45+rand()*.5,(rand()-.5)*.7);g.add(berry)}return addNode(g,'berry','WILD BERRIES',3,{x,z})}
function makeFiber(x,z){const g=new THREE.Group();for(let i=0;i<9;i++){const leaf=new THREE.Mesh(new THREE.ConeGeometry(.12,.85,4),grassMat);leaf.position.set((rand()-.5)*.6,.38,(rand()-.5)*.5);leaf.rotation.z=(rand()-.5)*.75;leaf.rotation.x=(rand()-.5)*.5;g.add(leaf)}return addNode(g,'fiber','DRY FIBER',2,{x,z})}
// A loose ring of useful finds near the landing site, then a broad forest beyond.
for(let i=0;i<85;i++){let a=rand()*Math.PI*2,r=12+rand()*74,x=Math.cos(a)*r,z=15+Math.sin(a)*r;if(Math.abs(x)<4&&z<4)continue;makeTree(x,z,.78+rand()*.46)}
for(let i=0;i<17;i++){let a=rand()*Math.PI*2,r=5+rand()*27;makeRock(Math.cos(a)*r,15+Math.sin(a)*r)}
for(let i=0;i<14;i++){let a=rand()*Math.PI*2,r=4+rand()*28;makeBush(Math.cos(a)*r,15+Math.sin(a)*r)}
for(let i=0;i<22;i++){let a=rand()*Math.PI*2,r=6+rand()*34;makeFiber(Math.cos(a)*r,15+Math.sin(a)*r)}
// Beacon landmark at the crest, visible through the trees as the sun falls.
const beacon=new THREE.Group();beacon.position.set(0,heightAt(0,-71),-71);scene.add(beacon);const plinth=new THREE.Mesh(new THREE.CylinderGeometry(1.25,1.8,1,6),mat(0x585f51));plinth.position.y=.5;plinth.castShadow=true;beacon.add(plinth);const beaconPost=new THREE.Mesh(new THREE.CylinderGeometry(.09,.16,4.2,8),mat(0x555a4b));beaconPost.position.y=3;beacon.add(beaconPost);const beaconCore=new THREE.Mesh(new THREE.OctahedronGeometry(.62,0),beaconMat);beaconCore.position.y=5.1;beacon.add(beaconCore);const beaconRing=new THREE.Mesh(new THREE.TorusGeometry(1.05,.045,7,32),mat(0xd8bc79));beaconRing.position.y=5.1;beaconRing.rotation.x=Math.PI/2;beacon.add(beaconRing);const beam=new THREE.Mesh(new THREE.CylinderGeometry(.12,.8,30,12,1,true),new THREE.MeshBasicMaterial({color:0xffce73,transparent:true,opacity:.08,side:THREE.DoubleSide}));beam.position.y=17;beacon.add(beam);beacon.userData.node=true;beacon.userData.type='beacon';beacon.userData.label='RIDGE BEACON';worldNodes.push(beacon);
// Small, readable low-poly wildlife silhouettes.
const wolves=[];function makeWolf(x,z){const g=new THREE.Group(),fur=mat(0x55594e),dark=mat(0x333a34);const body=new THREE.Mesh(new THREE.IcosahedronGeometry(.72,1),fur);body.scale.set(1.35,.72,.72);body.position.y=.82;g.add(body);const head=new THREE.Mesh(new THREE.IcosahedronGeometry(.42,1),fur);head.position.set(.8,1.12,0);head.scale.set(1.1,.85,.85);g.add(head);for(const s of [-1,1]){const ear=new THREE.Mesh(new THREE.ConeGeometry(.14,.37,5),dark);ear.position.set(.75,1.55,s*.23);g.add(ear);const leg=new THREE.Mesh(new THREE.CylinderGeometry(.09,.12,.58,5),dark);leg.position.set(s*.48,.36,s*.35);g.add(leg)}const tail=new THREE.Mesh(new THREE.ConeGeometry(.15,.55,5),fur);tail.position.set(-.92,1.03,0);tail.rotation.z=-1.5;g.add(tail);g.position.set(x,heightAt(x,z),z);scene.add(g);wolves.push({mesh:g,home:new THREE.Vector3(x,0,z),phase:rand()*8,attack:0,alive:true})}for(let i=0;i<5;i++){const a=rand()*Math.PI*2,r=33+rand()*28;makeWolf(Math.cos(a)*r,10+Math.sin(a)*r)}
const keys={};let pointer=false,interactNode=null,toastTimer=0,clockStart=6.7,fireLight=null,soundOn=false,ac=null,lastTime=performance.now();const raycaster=new THREE.Raycaster();raycaster.far=5.2;const dir=new THREE.Vector3();
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1900)}
function sound(freq=420,duration=.08){if(!soundOn)return;try{ac??=new AudioContext();const o=ac.createOscillator(),gain=ac.createGain();o.type='sine';o.frequency.value=freq;gain.gain.setValueAtTime(.035,ac.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ac.currentTime+duration);o.connect(gain);gain.connect(ac.destination);o.start();o.stop(ac.currentTime+duration)}catch{}}
function refresh(){for(const [id,val] of [['health',player.health],['food',player.food],['water',player.water]]){$(`#${id}-value`).textContent=Math.ceil(val);$(`#${id}-meter`).style.width=Math.max(0,val)+'%'}$('#temp-value').textContent=Math.round(player.temp)+'°';$('#temp-meter').style.width=Math.min(100,Math.max(0,(player.temp-25)*8.34))+'%';$('#wood-count').textContent=player.wood;$('#stone-count').textContent=player.stone;$('#fiber-count').textContent=player.fiber;$('#berry-count').textContent=player.berries;$('#axe-slot-label').textContent=player.axe?'equipped':'empty';$('#spear-slot-label').textContent=player.spear?'equipped':'empty';$('#fire-slot-label').textContent=player.fire?'built':'empty';document.querySelectorAll('.craft-btn').forEach(b=>b.disabled=!canCraft(b.id));updateObjectives()}
function canCraft(id){if(id==='craft-axe')return !player.axe&&player.stone>=2&&player.wood>=1;if(id==='craft-spear')return !player.spear&&player.wood>=2&&player.stone>=1;if(id==='craft-fire')return !player.fire&&player.wood>=3&&player.stone>=2;return false}
function updateObjectives(){const done=[player.axe,player.fire,player.pos.distanceTo(new THREE.Vector3(0,heightAt(0,-71)+player.pos.y-heightAt(0,15),-71))<4]; // distance is corrected below using horizontal distance
 done[2]=Math.hypot(player.pos.x,player.pos.z+71)<4&&player.axe&&player.fire;[['objective',done[0]],['objective-fire',done[1]],['objective-beacon',done[2]]].forEach(([id,yes])=>{$(`#${id}`).classList.toggle('complete',yes);$(`#${id} .objective-check`).textContent=yes?'✓':'○'});const n=done.slice(0,2).filter(Boolean).length+(Math.hypot(player.pos.x,player.pos.z+71)<4?1:0);$('#mission-count').textContent=`${n} / 3`;$('#mission-progress').style.width=`${n/3*100}%`}
function craft(type){if(!canCraft('craft-'+type)){toast('Not enough materials');return}if(type==='axe'){player.stone-=2;player.wood-=1;player.axe=true;toast('Stone axe crafted · wood yield increased')}if(type==='spear'){player.wood-=2;player.stone-=1;player.spear=true;toast('Wooden spear crafted · equip slot 3')}if(type==='fire'){player.wood-=3;player.stone-=2;player.fire=true;toast('Campfire kit packed · select slot 4 to place')}sound(680);refresh()}
function gather(){if(!interactNode)return;const node=interactNode;if(node.userData.type==='beacon'){if(!player.axe||!player.fire){toast('The beacon is cold. Complete your field directive first.');return}if(player.flare<1){toast('You need a signal flare');return}player.flare--;player.won=true;$('#end-kicker').textContent='EXPEDITION COMPLETE';$('#end-title').innerHTML='Signal<br><em>received.</em>';$('#end-copy').textContent='A distant searchlight cuts through the cedar canopy. You made it out.';showEnd();return}if(!node.userData.alive)return;const count=node.userData.quantity;switch(node.userData.type){case'tree':player.wood+=player.axe?count+1:count;break;case'stone':player.stone+=count;break;case'berry':player.berries+=count;break;case'fiber':player.fiber+=count;break}player.gathered+=count;node.userData.alive=false;scene.remove(node);toast(`${node.userData.label} · +${node.userData.type==='tree'?(player.axe?count+1:count):count} ${node.userData.type.toUpperCase()}`);sound(340);refresh()}
function eat(){if(player.berries<=0){toast('No berries · find a berry bush');return}player.berries--;player.food=Math.min(100,player.food+28);toast('Wild berries eaten · nutrition restored');sound(520);refresh()}
function drink(){if(player.water<99){player.water=Math.min(100,player.water+32);toast('Fresh mountain water · hydration restored');sound(600);refresh()}}
function placeFire(){if(!player.fire||player.slot!==3||player.firePos)return;const forward=new THREE.Vector3(-Math.sin(player.yaw),0,-Math.cos(player.yaw));const p=player.pos.clone().add(forward.multiplyScalar(2.6));p.y=heightAt(p.x,p.z);player.firePos=p;const g=new THREE.Group();g.position.copy(p);for(let i=0;i<4;i++){const log=new THREE.Mesh(new THREE.CylinderGeometry(.11,.12,1.1,6),trunkMat);log.position.y=.18;log.rotation.z=Math.PI/2;log.rotation.y=i*Math.PI/2;g.add(log)}const flameMat=new THREE.MeshBasicMaterial({color:0xff9538});const flame=new THREE.Mesh(new THREE.ConeGeometry(.34,1,7),flameMat);flame.position.y=.8;g.add(flame);scene.add(g);fireLight=new THREE.PointLight(0xff9b43,2.2,13);fireLight.position.set(p.x,p.y+1.6,p.z);scene.add(fireLight);player.fire=false;player.fire=true;toast('Campfire lit · stay close to keep warm');sound(760);refresh()}
function updateTarget(){camera.getWorldDirection(dir);raycaster.set(camera.position,dir);let hits=raycaster.intersectObjects(worldNodes,true);interactNode=null;let target=null;for(const h of hits){let o=h.object;while(o&& !o.userData.node)o=o.parent;if(o&&o.userData.node&&o.userData.alive!==false){target=o;break}}if(target){if(target.userData.type==='beacon'&&Math.hypot(player.pos.x,player.pos.z+71)>4)target=null;else interactNode=target}const box=$('#interaction');if(interactNode){let label=interactNode.userData.label;if(interactNode.userData.type==='beacon')label=player.axe&&player.fire?'ACTIVATE BEACON':'BEACON · DIRECTIVE INCOMPLETE';$('#interaction-text').textContent=label;box.classList.add('show')}else box.classList.remove('show')}

