function updateTarget(){camera.getWorldDirection(dir);raycaster.set(camera.position,dir);let hits=raycaster.intersectObjects(worldNodes,true);interactNode=null;let target=null;for(const h of hits){let o=h.object;while(o&& !o.userData.node)o=o.parent;if(o&&o.userData.node&&o.userData.alive!==false){target=o;break}}if(target){if(target.userData.type==='beacon'&&Math.hypot(player.pos.x,player.pos.z+71)>4)target=null;else interactNode=target}const box=$('#interaction');if(interactNode){let label=interactNode.userData.label;if(interactNode.userData.type==='beacon')label=player.axe&&player.fire?'ACTIVATE BEACON':'BEACON · DIRECTIVE INCOMPLETE';$('#interaction-text').textContent=label;box.classList.add('show')}else box.classList.remove('show')}

// A little first-person kit keeps the expedition grounded in the world.
const toolRoot=new THREE.Group();camera.add(toolRoot);toolRoot.position.set(.56,-.52,-.88);const sleeve=new THREE.Mesh(new THREE.CylinderGeometry(.11,.15,.55,7),mat(0x465344));sleeve.rotation.z=-.42;sleeve.position.set(.1,-.12,.1);toolRoot.add(sleeve);const glove=new THREE.Mesh(new THREE.IcosahedronGeometry(.15,1),mat(0x9a8061));glove.position.set(.12,.12,0);toolRoot.add(glove);const handle=new THREE.Mesh(new THREE.CylinderGeometry(.035,.05,.82,7),mat(0x79563a));handle.position.set(.04,.08,0);handle.rotation.z=-.37;toolRoot.add(handle);const axeHead=new THREE.Mesh(new THREE.BoxGeometry(.37,.24,.1),stoneLight);axeHead.position.set(.26,.39,0);axeHead.rotation.z=-.25;toolRoot.add(axeHead);const spearTip=new THREE.Mesh(new THREE.ConeGeometry(.1,.35,5),stoneLight);spearTip.position.set(.04,.57,0);toolRoot.add(spearTip);const handOnly=new THREE.Group();handOnly.add(sleeve.clone(),glove.clone());camera.add(handOnly);handOnly.position.copy(toolRoot.position);toolRoot.visible=false;handOnly.visible=true;
const pond=new THREE.Mesh(new THREE.CircleGeometry(1,32),new THREE.MeshStandardMaterial({color:0x72938d,roughness:.2,metalness:.18,transparent:true,opacity:.8}));pond.rotation.x=-Math.PI/2;pond.scale.set(7.5,4.2,1);pond.position.set(13,heightAt(13,-18)+.035,-18);scene.add(pond);const pondRing=new THREE.Mesh(new THREE.TorusGeometry(1,.12,4,36),mat(0x81906a));pondRing.rotation.x=Math.PI/2;pondRing.scale.set(7.5,4.2,1);pondRing.position.copy(pond.position).setY(pond.position.y-.035);scene.add(pondRing);
function useItem(){if(player.slot===3){if(player.fire&&!player.firePos)placeFire();else toast('Campfire kit unavailable')}else if(player.slot===4){if(Math.hypot(player.pos.x,player.pos.z+71)<4&&player.axe&&player.fire)gather();else toast('Signal flare · reach the ridge beacon')}else if(player.slot===2&&!player.spear)toast('Craft a wooden spear first')}
function selectSlot(n){player.slot=n;document.querySelectorAll('.slot').forEach((el,i)=>el.classList.toggle('active',i===n));toolRoot.visible=n===1&&player.axe||n===2&&player.spear;handOnly.visible=n===0||n===3||n===4}
function attack(){if(player.slot!==2||!player.spear){if(pointer&&player.slot!==0)useItem();return}let nearest=null,dist=4.2;for(const wolf of wolves){if(!wolf.alive)continue;const d=wolf.mesh.position.distanceTo(player.pos);if(d<dist){dist=d;nearest=wolf}}if(nearest){nearest.alive=false;scene.remove(nearest.mesh);player.gathered++;toast('Predator driven off · +1 hide');sound(185,.15)}else toast('Spear thrust');}
function pause(){if(!player.dead&&!player.won){$('#pause-screen').classList.remove('hidden');if(document.pointerLockElement)document.exitPointerLock()}}
function showEnd(){const elapsed=Math.floor(player.elapsed);$('#end-time').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(elapsed%60).padStart(2,'0')}`;$('#end-gathered').textContent=player.gathered;$('#end-screen').classList.remove('hidden');document.exitPointerLock?.()}
function die(){if(player.dead)return;player.dead=true;$('#end-kicker').textContent='EXPEDITION LOST';$('#end-title').innerHTML='The wild<br><em>remains.</em>';$('#end-copy').textContent='The northern reach claimed another traveler. The beacon still waits.';showEnd()}
function tick(dt){if($('#center-notice').classList.contains('hidden')===false||player.dead||player.won||!$('#pause-screen').classList.contains('hidden'))return;player.elapsed+=dt;const speed=keys.Shift?7:4.7;const fwd=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);let move=new THREE.Vector3(side,0,-fwd);if(move.lengthSq())move.normalize().multiplyScalar(speed*dt).applyAxisAngle(new THREE.Vector3(0,1,0),player.yaw);player.pos.x+=move.x;player.pos.z+=move.z;player.pos.x=Math.max(-86,Math.min(86,player.pos.x));player.pos.z=Math.max(-82,Math.min(87,player.pos.z));const ground=heightAt(player.pos.x,player.pos.z);player.pos.y=ground+1.72+(Math.sin(player.elapsed*11)*.035*(Math.abs(fwd)+Math.abs(side)));
// Survival rhythm: the light fades, thirst and hunger become urgent, fire buys warmth.
player.food=Math.max(0,player.food-dt*.095);player.water=Math.max(0,player.water-dt*.14);const phase=(player.elapsed/270)*Math.PI;const dusk=Math.max(0,Math.sin(phase));const nearFire=player.firePos&&player.pos.distanceTo(player.firePos)<8;const nearPond=Math.hypot(player.pos.x-13,player.pos.z+18)<9;player.temp=nearFire?37:36.4-dusk*8-(player.water<15?1:0);if(nearFire)player.temp=38;if(player.food===0||player.water===0)player.health=Math.max(0,player.health-dt*1.6);if(player.temp<31)player.health=Math.max(0,player.health-dt*.85);if(player.health<=0)die();if(keys.KeyR&&nearPond){if(!player._drinkCd||player.elapsed>player._drinkCd){drink();player._drinkCd=player.elapsed+2}}if(keys.KeyF){if(!player._eatCd||player.elapsed>player._eatCd){eat();player._eatCd=player.elapsed+1}}
// Wolves circle their territory, but pursue when the survivor gets too close.
let danger=false;for(const wolf of wolves){if(!wolf.alive)continue;const p=wolf.mesh.position,d=p.distanceTo(player.pos);if(d<13)danger=true;if(d<20){const toward=new THREE.Vector3(player.pos.x-p.x,0,player.pos.z-p.z).normalize();p.x+=toward.x*dt*(d<8?1.5:.65);p.z+=toward.z*dt*(d<8?1.5:.65);wolf.mesh.rotation.y=Math.atan2(toward.x,toward.z);if(d<1.6&&player.elapsed>wolf.attack){wolf.attack=player.elapsed+1.8;player.health=Math.max(0,player.health-8);toast('A wolf struck you · find shelter');sound(110,.2)}}else{wolf.phase+=dt*.25;p.x=wolf.home.x+Math.sin(wolf.phase)*2;p.z=wolf.home.z+Math.cos(wolf.phase)*2}p.y=heightAt(p.x,p.z);wolf.mesh.position.copy(p)}$('#danger-banner').classList.toggle('show',danger);
